            if (this.channel) {
                await this.channel.delete();
                await Cart.deleteOne({ channelId: this.channel.id });
            }
        } catch (err) {
            console.error('Erro ao tratar inatividade:', err);
        }
    }

    // -----------------------------------------------------------------------
    // Processamento de pagamento
    // -----------------------------------------------------------------------

    /**
     * Processa o pagamento após a confirmação do usuário.
     *
     * @param {Object} paymentResponse
     */
    async processPayment(paymentResponse) {
        try {
            if (!paymentResponse) {
                throw new Error('Resposta de pagamento inválida.');
            }

            const { id, attachment, pixCopyPasteCode } = paymentResponse;
            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);

            // Atualiza o embed com o resumo do carrinho
            await this.message.edit({
                embeds: [
                    new EmbedBuilder()
                        .setDescription(`### Resumo do Carrinho\n` +
                            `\n📨 **ID**: ${this.cartId}\n` +
                            `\n📦 **Produto**: ${this.productData.productName}\n` +
                            `\n✨ **Plano**: ${this.capitalizePlan(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias\n` +
                            `\n💸 **Total**: R$${totalAmount}`),
                    new EmbedBuilder()
                        .setDescription('- **Pague o Pix via QR CODE ou código pix abaixo**\n' +
                            '- O pagamento será verificado automaticamente\n' +
                            '- Expira em <t::R>')
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setCustomId('pixCopyPaste')
                            .setLabel('Código copia e cola')
                            .setEmoji('💰')
                            .setStyle(ButtonStyle.Secondary),
                        new ButtonBuilder()
                            .setCustomId('cancelPayment')
                            .setLabel('Cancelar Pedido')
                            .setStyle(ButtonStyle.Danger)
                    )
                ]
            });

            // Anexa o QR Code, se existir
            if (attachment) {
                await this.channel.send({ files: [attachment] });
            }

            // Monitora o status do pagamento a cada minuto
            const checkStatus = setInterval(async () => {
                try {
                    // Supondo que o PaymentProcessor tenha um método checkPaymentStatus
                    const status = await this.paymentProcessor.checkPaymentStatus(id);
                    console.log(`[Payment] - Status do pagamento (${id}): ${status}`);

                    if (status === 'approved') {
                        clearInterval(checkStatus);
                        await this.handleApprovedPayment(id);
                    } else if (status === 'cancelled') {
                        clearInterval(checkStatus);
                        await this.handleInactivity();
                    }
                    // Outros status podem ser tratados conforme necessidade
                } catch (err) {
                    console.error('Erro ao verificar status do pagamento:', err);
                }
            }, 60_000); // 60 segundos
        } catch (err) {
            console.error('Erro ao processar pagamento:', err);
        }
    }

    /**
     * Trata o pagamento aprovado.
     *
     * @param {String} paymentId
     */
    async handleApprovedPayment(paymentId) {
        try {
            const cart = await Cart.findOne({ channelId: this.channel.id });
            if (!cart || cart.status !== 'Aguardando...') return;

            cart.status = 'Processando';
            await cart.save();

            // Exemplo de atribuição de cargo (ID fixo – substitua conforme necessidade)
            const CARGO_CLIENT_ID = '995154994183548953';
            const member = this.interaction?.guild?.members.cache.get(this.user.id);
            if (member) {
                await member.roles.add(CARGO_CLIENT_ID).catch(() => console.log('Usuário já possui o cargo.'));
            }

            await this.channel.bulkDelete(50);
            await this.channel.send({ content: `✅ Pagamento Aprovado\n🆔 ID da Compra: ${this.cartId}` });

            // Embed de confirmação com opções de entrega
            const successEmbed = new EmbedBuilder()
                .setTitle('Pagamento Aprovado')
                .setAuthor({
                    name: this.client.user.username,
                    iconURL: this.client.user.displayAvatarURL({ dynamic: true })
                })
                .setFooter({
                    text: this.interaction?.guild?.name || 'N/A',
                    iconURL: this.interaction?.guild?.iconURL({ dynamic: true }) || null
                })
                .setDescription('**O pagamento foi aprovado! Para enviar o seu bot, preciso de algumas informações:**\n\n' +
                    '- **Nome que você irá querer na aplicação**\n' +
                    '- **ID que será setado como dono do bot**\n' +
                    '- **Token do Bot**\n\n' +
                    '⚠️ | Mantenha o token do bot seguro. Não compartilhe com ninguém!');

            await this.channel.send({
                embeds: [successEmbed],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setLabel('Enviar Bot')
                            .setEmoji('🎉')
                            .setStyle(ButtonStyle.Primary)
                            .setCustomId(`${this.selectedPlan}_${this.days * this.quantity}_${this.productId}_redeemBot`),
                        new ButtonBuilder()
                            .setLabel('Portal Desenvolvedor')
                            .setEmoji('🤖')
                            .setStyle(ButtonStyle.Link)
                            .setURL('https://discord.com/developers/applications/'),
                        new ButtonBuilder()
                            .setLabel('Tutorial')
                            .setEmoji('🔗')
